const b = ($input.first().json.body) || $input.first().json;

const system = [
  '당신은 한국 중소기업의 업무 자동화 진단 전문가입니다.',
  '입력된 업종·규모·도구·업무량을 근거로, 실행 가능하고 구체적인 자동화 진단 결과를 한국어로 작성합니다.',
  '수치(자동화 준비도, 절감 시간 등)는 입력값에 기반한 추정치이며 보장이 아닙니다. 과장하지 마세요.',
  'priorityTasks 는 이 회사가 실제로 겪을 법한 업무로 3~5개, 난이도는 낮음/중간/높음 중 하나로 표기합니다.',
  'recommendedStack 은 n8n, Supabase, OpenAI API, Telegram 등 실제 도입 가능한 도구명만 넣습니다.',
  'implementationSteps 는 주차별 단계로 4개 내외로 작성합니다.',
  '반드시 제공된 JSON 스키마 구조에 정확히 맞춰 응답합니다.',
].join('\n');

const user = [
  '아래 진단 입력값으로 자동화 진단 결과를 생성하세요.',
  '',
  '업종: ' + (b.industry || '(미입력)'),
  '직원 수: ' + (b.employeeCount || '(미입력)'),
  '홈페이지: ' + (b.websiteStatus || '(미입력)'),
  '현재 사용 도구: ' + ((b.currentTools || []).join(', ') || '없음'),
  '반복 업무: ' + ((b.repetitiveTasks || []).join(', ') || '없음'),
  '하루 반복 업무 시간: ' + (b.dailyHours || '(미입력)'),
  '담당 인원: ' + (b.staffCount || '(미입력)'),
  '월간 처리 건수: ' + (b.monthlyVolume || '(미입력)'),
  '도입 목적: ' + (b.purpose || '(미입력)'),
  '예산 범위: ' + (b.budgetRange || '(미입력)'),
  '구체적 어려움: ' + (b.painPoint || '(미입력)'),
].join('\n');

const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['automationScore', 'priorityTasks', 'totalEstimatedSavedHours', 'recommendedStack', 'implementationSteps', 'summary'],
  properties: {
    automationScore: { type: 'integer', minimum: 0, maximum: 100 },
    priorityTasks: {
      type: 'array', minItems: 3, maxItems: 5,
      items: {
        type: 'object', additionalProperties: false,
        required: ['name', 'reason', 'difficulty', 'estimatedMonthlySavedHours'],
        properties: {
          name: { type: 'string' },
          reason: { type: 'string' },
          difficulty: { type: 'string', enum: ['낮음', '중간', '높음'] },
          estimatedMonthlySavedHours: { type: 'integer' },
        },
      },
    },
    totalEstimatedSavedHours: {
      type: 'object', additionalProperties: false,
      required: ['min', 'max'],
      properties: { min: { type: 'integer' }, max: { type: 'integer' } },
    },
    recommendedStack: { type: 'array', items: { type: 'string' } },
    implementationSteps: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
  },
};

return [{
  json: {
    diagnosisId: b.diagnosisId,
    openaiBody: {
      model: 'gpt-4o',
      temperature: 0.4,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
      response_format: {
        type: 'json_schema',
        json_schema: { name: 'diagnosis_result', strict: true, schema },
      },
    },
  },
}];

const res = $input.first().json;
const diagnosisId = $('Build request').first().json.diagnosisId;

const fail = (reason) => [{ json: { diagnosisId, valid: false, reason } }];

if (res && res.error) return fail('openai_error: ' + (res.error.message || 'unknown'));
const choice = res && res.choices && res.choices[0];
if (!choice || !choice.message) return fail('no_choice');
if (choice.message.refusal) return fail('refusal: ' + choice.message.refusal);
if (choice.finish_reason && choice.finish_reason !== 'stop') return fail('finish_reason: ' + choice.finish_reason);

let p;
try { p = JSON.parse(choice.message.content); } catch (e) { return fail('json_parse: ' + e.message); }

for (const k of ['automationScore', 'priorityTasks', 'totalEstimatedSavedHours', 'recommendedStack', 'implementationSteps', 'summary']) {
  if (!(k in p)) return fail('missing_field: ' + k);
}
if (!Array.isArray(p.priorityTasks) || p.priorityTasks.length < 3 || p.priorityTasks.length > 5) return fail('priorityTasks_count');
for (const t of p.priorityTasks) {
  for (const k of ['name', 'reason', 'difficulty', 'estimatedMonthlySavedHours']) {
    if (!(k in t)) return fail('task_missing_key: ' + k);
  }
  if (!['낮음', '중간', '높음'].includes(t.difficulty)) return fail('bad_difficulty: ' + t.difficulty);
}
if (typeof p.totalEstimatedSavedHours?.min !== 'number' || typeof p.totalEstimatedSavedHours?.max !== 'number') return fail('bad_saved_hours');

// AI 필드 → diagnosis_results 컬럼 (n8n/workflows/README.md 매핑표)
return [{
  json: {
    diagnosisId,
    valid: true,
    row: {
      diagnosis_id: diagnosisId,
      automation_score: p.automationScore,
      recommended_tasks: p.priorityTasks,
      estimated_saved_hours: p.totalEstimatedSavedHours,
      recommended_stack: p.recommendedStack,
      implementation_steps: p.implementationSteps,
      ai_summary: p.summary,
    },
  },
}];
